<template><section><div class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><h1 class="text-2xl font-bold">{{t('clients.title')}}</h1><p class="mt-1 text-sm text-slate-500">{{total}} clients</p></div><button class="btn-primary" @click="openCreate">+ {{t('clients.new')}}</button></div><div class="card"><div class="mb-4 flex flex-wrap gap-2"><input v-model="search" @input="load" class="input max-w-sm" :placeholder="t('common.search')"/><select v-model="status" @change="load" class="input max-w-44"><option value="">{{t('common.all')}}</option><option value="active">{{t('common.active')}}</option><option value="suspended">{{t('common.suspended')}}</option><option value="expired">{{t('common.expired')}}</option></select><button v-if="selected.length" class="btn-danger" @click="bulk('suspend')">{{t('clients.suspend')}}</button><button v-if="selected.length" class="btn-ghost" @click="bulk('activate')">{{t('clients.activate')}}</button></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="text-start text-xs text-slate-500"><tr><th class="p-3"><input type="checkbox" @change="selectAll"/></th><th class="p-3 text-start">{{t('clients.email')}}</th><th class="p-3 text-start">{{t('common.status')}}</th><th class="p-3 text-start">{{t('clients.configs')}}</th><th class="p-3 text-start">{{t('traffic.used')}}</th><th class="p-3 text-end">{{t('common.actions')}}</th></tr></thead><tbody><tr v-for="u in users" :key="u.id" class="border-t border-white/5"><td class="p-3"><input v-model="selected" type="checkbox" :value="u.id"/></td><td class="p-3"><div>{{u.email||'—'}}</div><div class="mt-1 font-mono text-[10px] text-slate-600">{{u.uuid}}</div></td><td class="p-3"><span :class="badge(u.status)">{{u.status}}</span></td><td class="p-3">{{u.config_count}}</td><td class="p-3">{{fmt(u.traffic_used_bytes)}} <span v-if="u.traffic_limit_bytes">/ {{fmt(u.traffic_limit_bytes)}}</span></td><td class="p-3 text-end"><button class="btn-ghost me-1" @click="edit(u)">{{t('common.edit')}}</button><button class="btn-ghost me-1" @click="config(u.id)">{{t('clients.createConfig')}}</button><button class="btn-ghost me-1" @click="cloneUser(u.id)">{{t('clients.clone')}}</button><button class="btn-ghost me-1" @click="toggle(u)">{{u.status==='active'?t('clients.suspend'):t('clients.activate')}}</button><button class="btn-ghost me-1" @click="reset(u.id)">{{t('clients.reset')}}</button><button class="btn-danger" @click="remove(u.id)">{{t('clients.remove')}}</button></td></tr></tbody></table><div v-if="!users.length" class="p-10 text-center text-sm text-slate-600">{{t('common.noData')}}</div></div></div><div v-if="qr" class="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4"><div class="card max-w-sm text-center"><h2 class="mb-3 font-semibold">{{t('clients.createConfig')}}</h2><img v-if="qr" :src="qr" class="mx-auto rounded-xl bg-white p-3"/><p class="mt-3 break-all font-mono text-[11px] text-slate-500">{{qrUri}}</p><button class="btn-ghost mt-4" @click="qr='';qrUri=''">{{t('common.close')}}</button></div></div><div v-if="modal" class="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4"><form class="card w-full max-w-lg" @submit.prevent="save"><div class="mb-4 flex justify-between"><h2 class="text-lg font-semibold">{{editing?t('common.edit'):t('clients.new')}}</h2><button type="button" class="btn-ghost" @click="modal=false">×</button></div><div class="grid gap-3"><input v-model="form.email" class="input" :placeholder="t('clients.email')"/><input v-model.number="form.trafficLimitGb" class="input" type="number" min="0" step="0.1" :placeholder="t('clients.limit')"/><input v-model="form.expireAtText" class="input" type="datetime-local"/><input v-model="form.tagsText" class="input" :placeholder="t('clients.tags')"/><textarea v-model="form.note" class="input min-h-24" :placeholder="t('clients.note')"/></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="btn-ghost" @click="modal=false">{{t('common.cancel')}}</button><button class="btn-primary">{{t('common.save')}}</button></div></form></div></section></template>
<script setup lang="ts">import{ref}from'vue';import QRCode from 'qrcode';import{useI18n}from'vue-i18n';import{api}from'../api/client';const toLocalInput=(ms:number)=>{const d=new Date(ms);const p=(n:number)=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`};
const{t}=useI18n(),users=ref<any[]>([]),total=ref(0),search=ref(''),status=ref(''),selected=ref<number[]>([]),modal=ref(false),editing=ref<any>(null),qr=ref(''),qrUri=ref(''),form=ref<any>({email:'',trafficLimitGb:0,expireAtText:'',tagsText:'',note:''});const fmt=(n:number)=>{if(!n)return'0 B';const u=['B','KB','MB','GB','TB'];let i=0,x=n;while(x>=1024&&i<4){x/=1024;i++}return`${x.toFixed(x>=10||i===0?0:1)} ${u[i]}`};const badge=(s:string)=>s==='active'?'rounded-full bg-emerald-500/10 px-2 py-1 text-xs text-emerald-300':s==='suspended'?'rounded-full bg-amber-500/10 px-2 py-1 text-xs text-amber-300':'rounded-full bg-red-500/10 px-2 py-1 text-xs text-red-300';async function load(){const q=new URLSearchParams({search:search.value,status:status.value,pageSize:'100'});const d=await api.get<any>('/users?'+q);users.value=d.users;total.value=d.total;selected.value=[]}function openCreate(){editing.value=null;form.value={email:'',trafficLimitGb:0,expireAtText:'',tagsText:'',note:''};modal.value=true}function edit(u:any){editing.value=u;form.value={email:u.email||'',trafficLimitGb:u.traffic_limit_bytes/1024**3,expireAtText:u.expire_at?toLocalInput(u.expire_at):'',tagsText:u.tags||'',note:u.note||''};modal.value=true}async function save(){const body={email:form.value.email||null,trafficLimitBytes:Math.round((Number(form.value.trafficLimitGb)||0)*1024**3),expireAt:form.value.expireAtText?new Date(form.value.expireAtText).getTime():null,note:form.value.note||null,tags:form.value.tagsText.split(',').map((x:string)=>x.trim()).filter(Boolean)};if(editing.value)await api.patch(`/users/${editing.value.id}`,body);else await api.post('/users',body);modal.value=false;await load()}async function config(id:number){const protocol=prompt('Protocol: vless-ws or trojan-ws','vless-ws');if(!protocol||!['vless-ws','trojan-ws'].includes(protocol))return;const remark=prompt('Remark','3X-UI');const r=await api.post<any>('/configs',{userId:id,protocol,remark});qrUri.value=r.uri;qr.value=await QRCode.toDataURL(r.uri,{margin:2,width:280});try{await navigator.clipboard?.writeText(r.uri)}catch{/* clipboard is best effort; the URI is shown in the dialog */}}async function cloneUser(id:number){await api.post(`/users/${id}/clone`);await load()}async function toggle(u:any){await api.patch(`/users/${u.id}`,{status:u.status==='active'?'suspended':'active'});await load()}async function reset(id:number){if(confirm('Reset traffic usage?')){await api.post(`/users/${id}/reset-traffic`);await load()}}async function remove(id:number){if(confirm('Delete this client?')){await api.delete(`/users/${id}`);await load()}}async function bulk(action:string){await api.post('/users/bulk',{ids:selected.value,action});await load()}function selectAll(e:any){selected.value=e.target.checked?users.value.map(x=>x.id):[]}load();</script>
